    }));
    sm.action({ jobParams: { owner: 'epam', repo: 'dmtools-dart',
        silentToken: 'SILENT-TOKEN', sourceToken: 'PAT-TOKEN', rules: [RULES.update] } });

    assert.equal(updateCommands(sm).length, 0,
