        var cmd = makeCmd(function(command) {
            if (command.indexOf('git push') === 0) throw new Error(NON_FF_ERROR);
            if (command.indexOf('git merge --no-edit') === 0) {
                throw new Error('CONFLICT (content): Merge conflict in app.js\n' +
