        try { m.pushBranchWithSelfHeal(cmd, function() { return ''; }); }
        catch (e) { threw = e; }
        assert.ok(threw, 'no refspec to fetch — the original rejection surfaces');
        assert.equal(cmd.calls.length, 1, 'no half-applied healing');
